c=canvas.Canvas(str(OUT/'02-Drawings-DRAFT.pdf'),pagesize=(612,792));c.setTitle(TITLE+' - drawings');c.setAuthor('Prepared for Jason Daniel Zielinski')
def page(fig,title):
 c.setFont('Helvetica',8);c.drawString(58,765,'CONFIDENTIAL WORKING DRAFT - NOT FILED - 2026-11-03')
 c.setFont('Helvetica-Bold',14);c.drawString(58,730,f'FIG. {fig}');c.setFont('Helvetica',12);c.drawString(58,709,title)
 c.setFont('Helvetica',8);c.drawString(58,28,'Schematic; not to scale. Read with the accompanying specification.');c.drawRightString(554,28,str(fig))
def box(x,y,w,h,label):
 c.setLineWidth(1);c.rect(x,y,w,h);c.setFont('Helvetica',10)
 lines=label.split('\n');base=y+h/2+(len(lines)-1)*6
 for i,line in enumerate(lines):c.drawCentredString(x+w/2,base-i*12,line)
def arrow(x1,y1,x2,y2,label=''):
 import math
 c.line(x1,y1,x2,y2);a=math.atan2(y2-y1,x2-x1)
 for da in [-.45,.45]:c.line(x2,y2,x2-8*math.cos(a+da),y2-8*math.sin(a+da))
 if label:c.setFont('Helvetica',8);c.drawString((x1+x2)/2+5,(y1+y2)/2+5,label)
def note(y,text):
 p=Paragraph(html.escape(text),styles['body']);w,h=p.wrap(490,180);p.drawOn(c,60,y-h)
